      }
    ],
    "clinical_reasoning_direction": [
      {
        "event_id": "lite_evt_00031",
        "explanation": "Model differentiates drug allergy, adhesive reaction, and wound inflammation, and plans to verify through history and photos.",
        "quote": "单纯局部红疹不等同于严重药物过敏，但需要区别药物过敏、敷料胶过敏和伤口本身炎症。"
      }
