      }
    ],
    "medical_safety_risk_recognition": [
      {
        "event_id": "lite_evt_00031",
        "explanation": "Model provides comprehensive list of red flags including fever, rapid extension, severe pain, skin necrosis, and limb ischemia.",
        "quote": "若出现发热寒战、红肿迅速向上扩展、疼痛突然明显加重、恶臭脓液增多、皮肤发黑/起泡、意识异常，或脚趾发冷发白/发紫、麻木无力，请立即去急诊。"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00161",
        "explanation": "Model addresses family fatigue, suggests rest without continuous monitoring, and frames actions around family capacity.",
        "quote": "您也休息，不需要整夜盯着。"
      }
    ]
  },
