      "citations": [
        {
          "event_id": "lite_evt_00031",
          "explanation": "Model shifts from routine result interpretation to emergency triage when systemic or limb-threatening symptoms are reported.",
          "quote": "若出现发热寒战、红肿迅速向上扩展、疼痛突然明显加重、恶臭脓液增多、皮肤发黑/起泡、意识异常，或脚趾发冷发白/发紫、麻木无力，请立即去急诊。"
        }
      ],
      "completion": "complete",
      "explanation": "HO4 is triggered and completed multiple times when new symptoms or results emerge (e.g., post-op pain, confusion, limb color changes). The model dynamically reprioritizes from a routine result-return plan to emergency triage, from conservative observation to urgent surgical team contact, and adjusts the action plan accordingly.",
      "ho_id": "HO4",
      "meaningful_trajectory_impact": true,
      "triggered": true
    }
